import mezz.jei.gui.recipes.IRecipeLayoutWithButtons;
import net.minecraft.client.Minecraft;
import net.minecraft.client.player.LocalPlayer;
import net.minecraft.world.inventory.AbstractContainerMenu;

public class RecipeSortUtil {
    private static final Comparator<IRecipeLayoutWithButtons<?>> CRAFTABLE_COMPARATOR = RecipeSortUtil.createCraftableComparator();

    public static List<IRecipeCategory<?>> sortRecipeCategories(List<IRecipeCategory<?>> recipeCategories, RecipeTransferService recipeTransferService) {
        Minecraft minecraft = Minecraft.m_91087_();
        LocalPlayer player = minecraft.f_91074_;
        if (player == null) {
            return recipeCategories;
        }
        AbstractContainerMenu openContainer = player.f_36096_;
        if (openContainer == null) {
            return recipeCategories;
        }
        Comparator<IRecipeCategory> comparator = Comparator.comparing(r -> recipeTransferService.hasRecipeTransferHandler(openContainer, r)).reversed();
        return recipeCategories.stream().sorted(comparator).toList();
    }

    public static Comparator<IRecipeLayoutWithButtons<?>> getCraftableComparator() {
        return CRAFTABLE_COMPARATOR;
    }

    private static Comparator<IRecipeLayoutWithButtons<?>> createCraftableComparator() {
        return Comparator.comparingInt(r -> {
            IRecipeLayoutDrawable recipeLayout = r.getRecipeLayout();
            int missingCount = r.getMissingCountHint();
            if (missingCount == -1) {
                return 0;
